input.command:
S="C:/Users/[user]/AppData/Local/Temp/claude/b88cd0dcea610005/97f83947-aabe-451d-b0c9-7869a8caf154/scratchpad"; cat > "$S/app.js" <<'EOF'
const css = n => getComputedStyle(document.documentElement).getPropertyValue(n).trim();
const C = { ink: css('--ink'), card: css('--card'), line: css('--line'), brown: css('--brown'),
  green: css('--green-ink'), violet: css('--violet-ink'), pink: css('--pink-ink'), yellow: css('--yellow-ink'),
  greenF: css('--green'), yellowF: css('--yellow') };
const NAMES = { both: 'Soot + sulfate', soot: 'Soot only (Bardeen-like)', sulfate: 'Sulfate only (Brugger-like)', neither: 'Neither (control)' };
const X = DATA.x, YRS = DATA.years;
const when = y => y < 1 ? (Math.round(y * 12) === 0 ? 'impact' : 'month ' + Math.round(y * 12)) : 'year ' + Math.round(y);
const HOVER_T = YRS.map(when);
const TICKS = { tickvals: [0, 0.5, 1, 2, 1 + Math.log10(20), 1 + Math.log10(60)], ticktext: ['0', '6 mo', '1 yr', '10', '20', '60 yr'] };

function layout(extra) {
  return Object.assign({
    margin: { l: 46, r: 10, t: 8, b: 30 }, paper_bgcolor: 'rgba(0,0,0,0)', plot_bgcolor: 'rgba(0,0,0,0)',
    font: { family: 'Times New Roman, Times, serif', size: 13, color: C.ink },
    xaxis: Object.assign({ range: [0, 2.79], gridcolor: C.line, zeroline: false, linecolor: C.ink, tickmode: 'array' }, TICKS),
    yaxis: { gridcolor: C.line, zeroline: false, linecolor: C.ink },
    showlegend: false, hovermode: 'x unified',
    hoverlabel: { bgcolor: C.card, bordercolor: C.ink, font: { family: 'Times New Roman, Times, serif', color: C.ink } },
  }, extra);
}
function line(y, color, name, fmt, opts) {
  return Object.assign({ x: X, y, customdata: HOVER_T, mode: 'lines', name, line: { color, width: 2.6, shape: 'spline', smoothing: 0.4 },
    hovertemplate: `%{customdata}: <b>%{y:${fmt}}</b><extra>${name}</extra>` }, opts || {});
}
function control(y, fmt) {
  return { x: X, y, mode: 'lines', name: 'no impact', line: { color: C.ink, width: 1.2, dash: 'dash' }, opacity: 0.45, hoverinfo: 'skip' };
}
const pct = a => a.map(v => v * 100);
const cel = a => a.map(v => v - 273.15);
const CFG = { responsive: true, displayModeBar: false };

function draw(key) {
  const s = DATA.scenarios[key], n = DATA.scenarios.neither;
  const ctl = key !== 'neither';
  Plotly.react('p-trans', [ctl && control(pct(n.trans)),
    line(pct(s.trans), C.yellow, 'Sunlight', '.1f', { fill: 'tozeroy', fillcolor: 'rgba(217,181,74,.25)', hovertemplate: '%{customdata}: <b>%{y:.1f}%</b><extra>sunlight</extra>' })].filter(Boolean),
    layout({ yaxis: { range: [0, 105], gridcolor: C.line, zeroline: false, ticksuffix: '%' } }), CFG);
  Plotly.react('p-Ts', [ctl && control(cel(n.Ts)),
    line(cel(s.Ts), C.brown, 'Surface', '.1f', { hovertemplate: '%{customdata}: <b>%{y:.1f} °C</b><extra>surface</extra>' })].filter(Boolean),
    layout({ yaxis: { range: [-22, 20], gridcolor: C.line, zeroline: false, ticksuffix: '°' },
      shapes: [{ type: 'line', xref: 'paper', x0: 0, x1: 1, y0: 0, y1: 0, line: { color: C.violet, width: 1, dash: 'dot' } }],
      annotations: [{ xref: 'paper', x: 1, y: 0, yanchor: 'bottom', xanchor: 'right', text: 'freezing', showarrow: false, font: { size: 12, color: C.violet } }] }), CFG);
  Plotly.react('p-prod', [ctl && control(pct(n.prod)),
    line(pct(s.prod), C.green, 'Photosynthesis', '.1f', { fill: 'tozeroy', fillcolor: 'rgba(143,177,149,.3)', hovertemplate: '%{customdata}: <b>%{y:.1f}%</b><extra>photosynthesis</extra>' })].filter(Boolean),
    layout({ yaxis: { range: [0, 105], gridcolor: C.line, zeroline: false, ticksuffix: '%' } }), CFG);
  const lv = [['producers', C.green], ['herbivores', C.violet], ['predators', C.pink]];
  Plotly.react('p-web', lv.map(([nm, col], j) => line(s.web.map(r => r[j] * 100), col, nm, '.1f',
      { hovertemplate: `<b>%{y:.1f}%</b><extra>${nm}</extra>` })),
    layout({ showlegend: true, legend: { orientation: 'h', x: 0, y: -0.2, font: { size: 12 } }, margin: { l: 46, r: 10, t: 8, b: 52 },
