h=j('head.html'); a=j('app.js')
h=h.replace('</style>', j('dino.css')+'</style>')
h=h.replace('  <footer>', j('dino.html')+'\n  <footer>')
h=h.replace('</div>\n', '</div>\n<div id="flash" aria-hidden="true"></div>\n') if h.endswith('</div>\n') else h
assert h.rstrip().endswith('</div>')
h=h.rstrip()+'\n<div id="flash" aria-hidden="true"></div>\n'
old="""btn.addEventListener('click', () => {
  shown = pick(); btn.classList.remove('stale');
  document.getElementById('showing').textContent = NAMES[shown];
  draw(shown);
});"""
new="""btn.addEventListener('click', () => {
  shown = pick(); btn.classList.remove('stale'); btn.disabled = true;
  impact(() => { document.getElementById('showing').textContent = NAMES[shown]; draw(shown); })
    .finally(() => { btn.disabled = false; });
});"""
assert old in a; a=a.replace(old,new)
d=j('preview_data.json')
open(os.path.join(S,'kpg-website-preview.html'),'w',encoding='utf-8').write(h+'<script>\nconst DATA = '+d+';\n'+a+'\n'+j('dino.js')+'</script>\n')
EOF
