(function buildHerd() {
  const herd = document.getElementById('herd');
  herd.innerHTML = DINOS.map(([name, alive, vw, w, fill, P, B, eye, fly], i) => {
    const f = `var(${fill})`;
    const back = B.map(d => `<path d="${d}" fill="${f}" opacity=".6"/>`).join('');
    const front = P.map(d => `<path d="${d}" fill="${f}"/>`).join('');
    const nm = name === 'Tyrannosaurus rex' ? 'T. rex' : name;
    return `<figure class="dino${fly ? ' flyer' : ''}" style="--i:${i};--d:${i % 2 ? 1 : -1}">
      <svg viewBox="0 0 ${vw} 80" width="${w}" role="img" aria-label="${name}">${back}${front}<circle cx="${eye[0]}" cy="${eye[1]}" r="1.7" fill="var(--card)"/></svg>
      <figcaption><i>${nm}</i><span class="${alive ? 'alive' : ''}">${alive ? 'at impact' : 'earlier'}</span></figcaption></figure>`;
  }).join('');
})();

// Asteroid: fly in from the top-right corner, flash, shake, dinos panic, then the new graphs appear.
const REDUCED = matchMedia('(prefers-reduced-motion: reduce)').matches;
function impact(onHit) {
  if (REDUCED || !document.body.animate) { onHit(); return Promise.resolve(); }
  const grid = document.querySelector('.grid').getBoundingClientRect();
  const tx = grid.left + grid.width / 2, ty = Math.max(60, Math.min(grid.top + grid.height / 2, innerHeight / 2));
  const rock = document.createElement('div'); rock.id = 'rock'; document.body.appendChild(rock);
  const flash = document.getElementById('flash');
  flash.style.setProperty('--fx', tx + 'px'); flash.style.setProperty('--fy', ty + 'px');
  const fall = rock.animate([
    { transform: `translate(${innerWidth + 80}px, -120px) scale(.55) rotate(0deg)` },
    { transform: `translate(${tx}px, ${ty}px) scale(1.15) rotate(260deg)` }],
    { duration: 850, easing: 'cubic-bezier(.55,0,.9,.5)', fill: 'forwards' });
  return fall.finished.then(() => {
    rock.remove();
    flash.animate([{ opacity: 0 }, { opacity: 1, offset: .12 }, { opacity: 0 }], { duration: 1100, easing: 'ease-out' });
    document.querySelector('.main').animate([{ transform: 'translate(0,0)' }, { transform: 'translate(-7px,4px)' },
      { transform: 'translate(6px,-5px)' }, { transform: 'translate(-4px,3px)' }, { transform: 'translate(0,0)' }], { duration: 420 });
    const herd = document.getElementById('herd');
    herd.classList.remove('panic'); void herd.offsetWidth; herd.classList.add('panic');
    setTimeout(() => herd.classList.remove('panic'), 2300);
    onHit();
  });
}

