/* dinosaur footer + asteroid */
.herd-wrap { background: var(--card); border: 1px solid var(--line); border-radius: 6px; padding: 14px 14px 0; overflow: hidden; }
.herd-wrap h2 { margin: 0; font-size: 20px; }
.herd-wrap > p { margin: 2px 0 0; font-size: 14px; max-width: 75ch; }
.herd { display: flex; flex-wrap: wrap; align-items: flex-end; justify-content: center; gap: 4px 18px; padding: 18px 0 0;
  border-bottom: 10px solid var(--brown); position: relative; }
.herd::after { content: ""; position: absolute; left: -14px; right: -14px; bottom: 0; height: 3px; background: var(--green); }
.dino { display: flex; flex-direction: column; align-items: center; gap: 2px; margin: 0; text-align: center; max-width: 100%; }
.dino svg { display: block; height: auto; max-width: 100%; overflow: visible; transform-origin: 50% 100%;
  animation: idle 3.4s ease-in-out infinite; animation-delay: calc(var(--i) * -0.37s); }
.dino.flyer svg { animation: fly 4s ease-in-out infinite; animation-delay: calc(var(--i) * -0.4s); }
.dino figcaption { font-size: 14px; line-height: 1.15; padding-bottom: 6px; }
.dino figcaption i { font-weight: 700; }
.dino figcaption span { display: block; font-size: 11px; letter-spacing: .06em; text-transform: uppercase; opacity: .7; }
.dino figcaption span.alive { opacity: 1; color: var(--green-ink); font-weight: 700; }
@keyframes idle { 0%,100% { transform: scaleY(1) rotate(0deg); } 50% { transform: scaleY(1.025) rotate(-0.6deg); } }
@keyframes fly { 0%,100% { transform: translateY(-6px); } 50% { transform: translateY(4px) rotate(2deg); } }
.herd.panic .dino svg { animation: panic .32s ease-in-out 6 alternate; animation-delay: calc(var(--i) * .03s); }
@keyframes panic {
  0% { transform: translateX(calc(var(--d) * -10px)) translateY(0); }
  50% { transform: translateX(0) translateY(-9px) rotate(calc(var(--d) * 4deg)); }
  100% { transform: translateX(calc(var(--d) * 12px)) translateY(0); } }

#rock { position: fixed; left: 0; top: 0; width: 44px; height: 44px; margin: -22px 0 0 -22px; border-radius: 46% 54% 50% 50%;
  background: radial-gradient(circle at 35% 35%, var(--peach), var(--brown) 45%, var(--ink) 95%); z-index: 50; pointer-events: none; }
#rock::before { content: ""; position: absolute; top: 50%; left: 50%; width: 180px; height: 26px; margin-top: -13px;
  transform-origin: 0 50%; transform: rotate(-35deg); border-radius: 13px;
  background: linear-gradient(90deg, rgb(225 188 167 / .9), rgb(217 181 74 / .5) 40%, transparent); z-index: -1; }
#flash { position: fixed; inset: 0; z-index: 49; pointer-events: none; opacity: 0;
  background: radial-gradient(circle at var(--fx, 50%) var(--fy, 50%), #fff6e0 0, var(--yellow) 12%, rgb(186 108 63 / .55) 35%, rgb(44 36 26 / .25) 70%); }
#run:disabled { opacity: .7; cursor: progress; }

