  const sx = innerWidth + 120, sy = -140;
  const ang = Math.atan2(sy - ty, sx - tx) * 180 / Math.PI;     // tail points back along the path
  const rock = document.createElement('div'); rock.id = 'rock';
  rock.innerHTML = `<div class="tail" style="transform:rotate(${ang}deg)"></div><div class="stone"></div>`;
  document.body.appendChild(rock);
  rock.querySelector('.stone').animate([{ transform: 'rotate(0)' }, { transform: 'rotate(300deg)' }], { duration: 2600 });
  await rock.animate([{ transform: `translate(${sx}px, ${sy}px) scale(.6)` }, { transform: `translate(${tx}px, ${ty}px) scale(1.1)` }],
    { duration: 2600, easing: 'cubic-bezier(.35,0,.85,.55)', fill: 'forwards' }).finished;
  await flash.animate([{ opacity: 0 }, { opacity: 1 }], { duration: 160, fill: 'forwards' }).finished;
  rock.remove();
  onHit();
  await txt.animate([{ opacity: 0, transform: 'translateY(8px)' }, { opacity: 1, transform: 'none' }], { duration: 450, fill: 'forwards' }).finished;
  await wait(1500);
  await flash.animate([{ opacity: 1 }, { opacity: 0 }], { duration: 1100, easing: 'ease-in', fill: 'forwards' }).finished;
