// Animals alive at the K-Pg impact. Drawings face right; [viewBox width, height px, fill token, front paths, back paths, eye]
const SPECIES = {
  trike: { name: 'Triceratops', diet: 'h', vw: 120, h: 60, fill: '--ink',
    P: ['M2 40 Q20 26 50 26 Q76 26 84 38 L96 40 Q110 42 114 50 L112 56 L104 54 Q96 56 90 54 Q80 58 70 58 Q40 60 24 52 Q10 48 2 40Z','M84 44 L78 18 Q90 8 100 18 L96 42Z','M98 36 L119 22 L102 40Z','M110 46 L117 39 L115 48Z','M30 52 L42 52 L42 74 L48 76 L30 76Z','M72 54 L84 54 L84 74 L90 76 L72 76Z'],
    B: ['M96 40 L114 30 L100 43Z','M44 54 L52 54 L52 76 L44 76Z'], eye: [101, 44] },
  alamo: { name: 'Alamosaurus', diet: 'h', vw: 160, h: 86, fill: '--green-ink',
    P: ['M2 44 Q30 36 44 34 Q60 28 80 30 Q96 30 110 18 Q124 6 136 4 L148 4 Q154 6 152 10 L140 12 Q128 14 118 28 Q108 44 100 52 Q86 62 66 62 Q48 62 38 54 Q24 50 2 44Z','M44 54 L56 54 L56 76 L44 76Z','M86 54 L98 54 L98 76 L86 76Z'],
    B: ['M56 58 L65 58 L65 76 L56 76Z','M97 50 L105 48 L105 76 L97 76Z'], eye: [146, 7] },
  pachy: { name: 'Pachycephalosaurus', diet: 'h', vw: 112, h: 50, fill: '--pink-ink',
    P: ['M4 40 Q28 32 50 32 Q66 32 76 30 L84 26 Q85 16 95 15 Q106 16 107 26 L108 32 Q106 36 100 36 L92 36 Q88 44 80 48 Q66 56 52 54 Q34 50 4 40Z','M50 50 L60 50 L62 62 L60 74 L68 76 L52 76 L54 62Z','M84 42 L88 50 L86 50 L82 44Z'],
    B: ['M62 50 L68 52 L70 64 L68 74 L74 76 L62 76 L63 64Z'], eye: [100, 27] },
  trex: { name: 'T. rex', diet: 'c', vw: 120, h: 74, fill: '--brown',
    P: ['M2 38 Q28 28 50 28 Q66 26 78 22 L100 18 Q114 18 116 28 L114 34 L100 34 L104 38 L90 40 Q84 50 72 54 Q58 58 46 52 Q28 44 2 38Z','M46 48 L60 48 L62 62 L60 74 L68 76 L50 76 L52 62Z','M86 42 L92 46 L90 48 L84 45Z'],
    B: ['M60 50 L68 52 L70 64 L68 74 L74 76 L62 76 L62 64Z'], eye: [102, 23] },
  quetz: { name: 'Quetzalcoatlus', diet: 'c', fly: 1, vw: 140, h: 52, fill: '--violet-ink',
    P: ['M48 44 L20 4 Q42 12 70 42Z','M44 44 Q56 38 68 44 Q60 52 46 50Z','M64 42 Q80 34 92 34 L94 32 Q100 26 106 30 L138 36 L106 38 Q98 40 94 38 Q80 40 66 48Z','M100 28 L93 16 L105 28Z','M46 48 L28 54 L30 56 L48 51Z'],
    B: ['M50 46 L8 30 Q30 28 64 44Z'], eye: [104, 32] },
};
const HERB = ['trike', 'pachy', 'alamo'], CARN = ['trex', 'quetz'];
const MAX_H = 8, MAX_C = 6;   // full herd sizes for the drawing (assumed)
const REDUCED = matchMedia('(prefers-reduced-motion: reduce)').matches;
let beasts = [], chasing = false;
const rnd = (a, b) => a + Math.random() * (b - a);
const later = (ms, f) => setTimeout(f, ms);

// ---------- scenery: ferns along the bottom, a few Cretaceous trees behind ----------
function frondTile() {
  const W = 96, H = 34, out = [];
  const frond = (x0, h, lean, col) => {
    const P = (t) => { const x1 = x0 + lean * .3, y1 = H - h * .7, x2 = x0 + lean, y2 = H - h, u = 1 - t;
      return [u * u * x0 + 2 * u * t * x1 + t * t * x2, u * u * H + 2 * u * t * y1 + t * t * y2]; };
    let d = `M${x0} ${H}`;
    for (let t = .1; t <= 1.001; t += .1) { const [x, y] = P(t); d += ` L${x.toFixed(1)} ${y.toFixed(1)}`; }
    out.push(`<path d="${d}" stroke="${col}" stroke-width="1.4" fill="none"/>`);
    for (let t = .18; t < .95; t += .085) {
      const [x, y] = P(t), [xa, ya] = P(t + .01); let nx = -(ya - y), ny = xa - x; const n = Math.hypot(nx, ny); nx /= n; ny /= n;
      const len = 7 * (1 - t) + 1.5;
      out.push(`<path d="M${x.toFixed(1)} ${y.toFixed(1)} l${(nx * len + (xa - x) * 30).toFixed(1)} ${(ny * len - 1).toFixed(1)} M${x.toFixed(1)} ${y.toFixed(1)} l${(-nx * len + (xa - x) * 30).toFixed(1)} ${(-ny * len - 1).toFixed(1)}" stroke="${col}" stroke-width="2" stroke-linecap="round"/>`);
    }
  };
  frond(8, 30, 10, '#4f7a58'); frond(30, 22, -8, '#8fb195'); frond(44, 32, -12, '#4f7a58');
  frond(60, 26, 9, '#8fb195'); frond(78, 31, -6, '#4f7a58'); frond(90, 20, 6, '#8fb195');
  return `<svg xmlns="http://www.w3.org/2000/svg" width="${W}" height="${H}">${out.join('')}</svg>`;
}
function araucaria(h) {
  let s = `<rect x="28" y="12" width="4" height="108" fill="var(--brown)"/>`;
  for (let k = 0; k < 7; k++) { const y = 10 + k * 14, w = 6 + k * 3.4; s += `<path d="M30 ${y} L${30 - w} ${y + 12} L${30 + w} ${y + 12}Z" fill="var(--green-ink)"/>`; }
  return `<svg viewBox="0 0 60 120" height="${h}" width="${h / 2}">${s}</svg>`;
}
function cycad(h) {
  let s = `<path d="M25 50 L26 30 L34 30 L35 50Z" fill="var(--brown)"/>`;
  for (let a = -75; a <= 75; a += 25) s += `<ellipse cx="30" cy="12" rx="3.5" ry="17" fill="var(--green-ink)" transform="rotate(${a} 30 30)"/>`;
  return `<svg viewBox="0 0 60 50" height="${h}" width="${h * 1.2}">${s}</svg>`;
}
function treefern(h) {
  let s = `<path d="M34 100 Q38 60 35 30" stroke="var(--brown)" stroke-width="4" fill="none"/>`;
  for (let a = -120; a <= 120; a += 30) s += `<ellipse cx="35" cy="8" rx="4" ry="22" fill="var(--green)" transform="rotate(${a} 35 30)"/>`;
  return `<svg viewBox="0 0 70 100" height="${h}" width="${h * .7}">${s}</svg>`;
}
function scenery() {
  const tile = 'data:image/svg+xml,' + encodeURIComponent(frondTile());
  document.querySelector('.grass').style.background =
    `url("${tile}") repeat-x left bottom / 96px 34px, linear-gradient(transparent 30px, var(--green-ink) 30px)`;
  const T = [[4, araucaria(118)], [21, cycad(46)], [37, treefern(92)], [58, araucaria(104)], [74, cycad(40)], [90, treefern(84)]];
  document.getElementById('trees').innerHTML = T.map(([x, s]) => `<div class="tree" style="left:${x}%">${s}</div>`).join('');
}

// ---------- herd size from the model ----------
function lowest(key, j) {
  const web = DATA.scenarios[key].web; let k = 0;
  web.forEach((r, i) => { if (r[j] < web[k][j]) k = i; });
  return { frac: DATA.scenarios[key].report.levels[j].min, year: DATA.years[k] };
}
function counts(key) {
  const h = lowest(key, 1), c = lowest(key, 2);
  return { h: Math.max(1, Math.round(MAX_H * Math.min(1, h.frac))), c: Math.max(1, Math.round(MAX_C * Math.min(1, c.frac))), hy: h.year, cy: c.year };
}
function svgFor(s) {
  const f = `var(${s.fill})`, w = Math.round(s.h * s.vw / 80);
  return `<svg viewBox="0 0 ${s.vw} 80" width="${w}" height="${s.h}" role="img" aria-label="${s.name}">` +
    s.B.map(d => `<path d="${d}" fill="${f}" opacity=".6"/>`).join('') + s.P.map(d => `<path d="${d}" fill="${f}"/>`).join('') +
    `<circle cx="${s.eye[0]}" cy="${s.eye[1]}" r="1.7" fill="var(--card)"/></svg>`;
}

// ---------- one animal ----------
function spawn(sp, x, dir, i) {
  const s = SPECIES[sp], el = document.createElement('div');
  el.className = 'beast' + (s.fly ? ' flyer' : ''); el.style.setProperty('--i', i);
  el.style.left = x + '%';
  el.innerHTML = `<div class="face" style="transform:scaleX(${dir})">${svgFor(s)}</div>`;
  document.getElementById('field').appendChild(el);
  return { el, face: el.firstChild, x, dir, sp, t: 0, busy: false, gone: false };
}
function face(b, d) { b.dir = d; b.face.style.transform = `scaleX(${d})`; }
function move(b, nx, secs, cls) {
  face(b, nx >= b.x ? 1 : -1);
  b.el.style.transition = `left ${secs}s ${cls === 'running' ? 'ease-out' : 'linear'}`;
  b.el.classList.add(cls); b.x = nx; b.el.style.left = nx + '%';
  return new Promise(r => later(secs * 1000, () => { b.el.classList.remove(cls); r(); }));
}
function schedule(b, ms) { clearTimeout(b.t); if (!REDUCED) b.t = later(ms ?? rnd(4000, 10000), () => act(b)); }

function buildHerd(key) {
  beasts.forEach(b => { clearTimeout(b.t); b.gone = true; });
  chasing = false;
  const n = counts(key), field = document.getElementById('field');
  const yr = y => y < 1 ? Math.round(y * 12) + ' mo' : 'yr ' + Math.round(y);
  document.getElementById('herdinfo').innerHTML = key === 'neither'
    ? `Full herd: <b>${n.h} herbivores</b>, <b class="c">${n.c} predators</b>. No impact, nothing lost.`
    : `At the worst point: <b>${n.h} of ${MAX_H} herbivores</b> (${yr(n.hy)}), <b class="c">${n.c} of ${MAX_C} predators</b> (${yr(n.cy)})`;
  const list = [];
  for (let i = 0; i < n.h; i++) list.push(HERB[i % HERB.length]);
  for (let i = 0; i < n.c; i++) list.push(CARN[i % CARN.length]);
  list.sort(() => Math.random() - .5);
  field.innerHTML = '';
  beasts = list.map((sp, i) => {
    const b = spawn(sp, 6 + (i + rnd(.2, .8)) / list.length * 86, Math.random() < .5 ? -1 : 1, i);
    schedule(b, rnd(1500, 6000));
    return b;
  });
}

// ---------- behaviours: graze, stroll, turn, wander off (and a new kind walks on), T. rex chase, Pachy headbutt ----------
function act(b) {
  if (b.gone) return;
  schedule(b);
  if (b.busy) return;
  const r = Math.random(), s = SPECIES[b.sp];
  if (s.fly) {                                     // Quetzalcoatlus glides around overhead
    if (r < .1) return leave(b);
    return void move(b, Math.min(94, Math.max(6, b.x + rnd(-30, 30))), rnd(4, 7), 'gliding');
  }
  if (b.sp === 'trex' && r < .2 && !chasing) { const prey = beasts.find(o => SPECIES[o.sp].diet === 'h' && !o.busy && !o.gone); if (prey) return chase(b, prey); }
  if (b.sp === 'pachy' && r < .3) { const mate = beasts.find(o => o !== b && o.sp === 'pachy' && !o.busy && !o.gone); if (mate) return headbutt(b, mate); }
  if (r < .08) return leave(b);
  if (r < .5) { b.el.classList.add('graze'); later(2800, () => b.el.classList.remove('graze')); return; }
  if (r < .8) {
    const nx = b.x + b.dir * rnd(3, 9);
    if (nx < 4 || nx > 96) return face(b, -b.dir);
    return void move(b, nx, Math.abs(nx - b.x) * .5, 'walking');
  }
  face(b, -b.dir);
}
async function leave(b) {
  b.busy = true;
  const edge = b.x < 50 ? -12 : 112;
  await move(b, edge, Math.abs(edge - b.x) * .32, SPECIES[b.sp].fly ? 'gliding' : 'walking');
  if (b.gone) return;
  b.gone = true; clearTimeout(b.t); b.el.remove();
  const pool = SPECIES[b.sp].diet === 'h' ? HERB : CARN;      // same food-web level, different kind
  const others = pool.filter(k => k !== b.sp);
  const sp = others[Math.floor(Math.random() * others.length)] || b.sp;
  const from = Math.random() < .5 ? -12 : 112;
  const nb = spawn(sp, from, from < 0 ? 1 : -1, beasts.length);
  beasts[beasts.indexOf(b)] = nb;
  nb.busy = true;
  later(400, async () => {
    await move(nb, from < 0 ? rnd(8, 40) : rnd(60, 92), rnd(5, 8), SPECIES[sp].fly ? 'gliding' : 'walking');
    nb.busy = false; schedule(nb);
  });
}
function chase(rex, prey) {
  chasing = true; rex.busy = prey.busy = true;
  const d = prey.x >= rex.x ? 1 : -1;
  const goal = Math.min(95, Math.max(5, prey.x + d * rnd(18, 28)));
  face(rex, d);
  later(350, () => move(prey, goal, 1.9, 'running'));
  later(550, () => move(rex, Math.min(95, Math.max(5, goal - d * 9)), 1.9, 'running').then(() => {
    later(700, () => { rex.busy = prey.busy = false; chasing = false; });
  }));
}
function headbutt(a, b) {
  a.busy = b.busy = true;
  const [L, R] = a.x <= b.x ? [a, b] : [b, a];
  const fw = document.getElementById('field').clientWidth || innerWidth;
  const half = 31 / fw * 100;                       // about 62 px between centres puts the domes together
  const mid = Math.min(90, Math.max(10, (L.x + R.x) / 2));
  const secs = Math.max(.8, Math.max(Math.abs(mid - half - L.x), Math.abs(mid + half - R.x)) * .35);
  [[L, mid - half, 1], [R, mid + half, -1]].forEach(([o, nx, d]) => {
    move(o, nx, secs, 'walking').then(() => {
      face(o, d);
      later(500, () => o.el.classList.add('butt'));
      later(2900, () => { o.el.classList.remove('butt'); o.busy = false; });
    });
  });
}
function scatter() {
  chasing = false;
  beasts.forEach(b => { b.busy = false; b.el.classList.remove('butt', 'graze'); move(b, rnd(5, 93), 1.3, 'running'); });
}

// ---------- asteroid: slow fall onto the herd, light-tan white-out with the scenario name, then fade back ----------
const wait = ms => new Promise(r => setTimeout(r, ms));
async function impact(name, onHit) {
  const flash = document.getElementById('flash'), txt = document.getElementById('flash-text');
  txt.innerHTML = `Simulation controls now showing <b>${name}</b>`;
  if (REDUCED || !document.body.animate) { onHit(); return; }
  const tx = innerWidth * rnd(.35, .65), ty = innerHeight - 55;
  const sx = innerWidth + 120, sy = -140;
  const ang = Math.atan2(sy - ty, sx - tx) * 180 / Math.PI;     // tail points back along the path
  const rock = document.createElement('div'); rock.id = 'rock';
  rock.innerHTML = `<div class="tail" style="transform:rotate(${ang}deg)"></div><div class="stone"></div>`;
  document.body.appendChild(rock);
  rock.querySelector('.stone').animate([{ transform: 'rotate(0)' }, { transform: 'rotate(300deg)' }], { duration: 2600 });
  await rock.animate([{ transform: `translate(${sx}px, ${sy}px) scale(.6)` }, { transform: `translate(${tx}px, ${ty}px) scale(1.1)` }],
    { duration: 2600, easing: 'cubic-bezier(.35,0,.85,.55)', fill: 'forwards' }).finished;
  await flash.animate([{ opacity: 0 }, { opacity: 1 }], { duration: 160, fill: 'forwards' }).finished;
  rock.remove();
  onHit();
  await txt.animate([{ opacity: 0, transform: 'translateY(8px)' }, { opacity: 1, transform: 'none' }], { duration: 450, fill: 'forwards' }).finished;
  await wait(1500);
  await flash.animate([{ opacity: 1 }, { opacity: 0 }], { duration: 1100, easing: 'ease-in', fill: 'forwards' }).finished;
  txt.animate([{ opacity: 0 }], { duration: 0, fill: 'forwards' });
  scatter();
}
scenery();

