    }
  };
  frond(8, 30, 10, '#4f7a58'); frond(30, 22, -8, '#8fb195'); frond(44, 32, -12, '#4f7a58');
  frond(60, 26, 9, '#8fb195'); frond(78, 31, -6, '#4f7a58'); frond(90, 20, 6, '#8fb195');
  return `<svg xmlns="http://www.w3.org/2000/svg" width="${W}" height="${H}">${out.join('')}</svg>`;
}
function araucaria(h) {
  let s = `<rect x="28" y="12" width="4" height="108" fill="var(--brown)"/>`;
  for (let k = 0; k < 7; k++) { const y = 10 + k * 14, w = 6 + k * 3.4; s += `<path d="M30 ${y} L${30 - w} ${y + 12} L${30 + w} ${y + 12}Z" fill="var(--green-ink)"/>`; }
