  const tx = innerWidth * rnd(.35, .65), ty = innerHeight - 55;
  const sx = innerWidth + 120, sy = -140;
  const ang = Math.atan2(sy - ty, sx - tx) * 180 / Math.PI;     // tail points back along the path
