    schedule(b, rnd(1500, 6000));
    return b;
  });
}

// ---------- behaviours: graze, stroll, turn, wander off (and a new kind walks on), T. rex chase, Pachy headbutt ----------
function act(b) {
  if (b.gone) return;
  schedule(b);
  if (b.busy) return;
  const r = Math.random(), s = SPECIES[b.sp];
  if (s.fly) {                                     // Quetzalcoatlus glides around overhead
    if (r < .1) return leave(b);
    return void move(b, Math.min(94, Math.max(6, b.x + rnd(-30, 30))), rnd(4, 7), 'gliding');
  }
  if (b.sp === 'trex' && r < .2 && !chasing) { const prey = beasts.find(o => SPECIES[o.sp].diet === 'h' && !o.busy && !o.gone); if (prey) return chase(b, prey); }
  if (b.sp === 'pachy' && r < .3) { const mate = beasts.find(o => o !== b && o.sp === 'pachy' && !o.busy && !o.gone); if (mate) return headbutt(b, mate); }
  if (r < .08) return leave(b);
  if (r < .5) { b.el.classList.add('graze'); later(2800, () => b.el.classList.remove('graze')); return; }
  if (r < .8) {
    const nx = b.x + b.dir * rnd(3, 9);
    if (nx < 4 || nx > 96) return face(b, -b.dir);
    return void move(b, nx, Math.abs(nx - b.x) * .5, 'walking');
  }
  face(b, -b.dir);
}
async function leave(b) {
  b.busy = true;
  const edge = b.x < 50 ? -12 : 112;
  await move(b, edge, Math.abs(edge - b.x) * .32, SPECIES[b.sp].fly ? 'gliding' : 'walking');
  if (b.gone) return;
  b.gone = true; clearTimeout(b.t); b.el.remove();
  const pool = SPECIES[b.sp].diet === 'h' ? HERB : CARN;      // same food-web level, different kind
  const others = pool.filter(k => k !== b.sp);
  const sp = others[Math.floor(Math.random() * others.length)] || b.sp;
  const from = Math.random() < .5 ? -12 : 112;
  const nb = spawn(sp, from, from < 0 ? 1 : -1, beasts.length);
  beasts[beasts.indexOf(b)] = nb;
  nb.busy = true;
  later(400, async () => {
    await move(nb, from < 0 ? rnd(8, 40) : rnd(60, 92), rnd(5, 8), SPECIES[sp].fly ? 'gliding' : 'walking');
    nb.busy = false; schedule(nb);
  });
}
function chase(rex, prey) {
  chasing = true; rex.busy = prey.busy = true;
  const d = prey.x >= rex.x ? 1 : -1;
  const goal = Math.min(95, Math.max(5, prey.x + d * rnd(18, 28)));
  face(rex, d);
  later(350, () => move(prey, goal, 1.9, 'running'));
  later(550, () => move(rex, Math.min(95, Math.max(5, goal - d * 9)), 1.9, 'running').then(() => {
    later(700, () => { rex.busy = prey.busy = false; chasing = false; });
  }));
}
function headbutt(a, b) {
  a.busy = b.busy = true;
  const [L, R] = a.x <= b.x ? [a, b] : [b, a];
  const fw = document.getElementById('field').clientWidth || innerWidth;
  const half = 31 / fw * 100;                       // about 62 px between centres puts the domes together
  const mid = Math.min(90, Math.max(10, (L.x + R.x) / 2));
  const secs = Math.max(.8, Math.max(Math.abs(mid - half - L.x), Math.abs(mid + half - R.x)) * .35);
  [[L, mid - half, 1], [R, mid + half, -1]].forEach(([o, nx, d]) => {
    move(o, nx, secs, 'walking').then(() => {
      face(o, d);
      later(500, () => o.el.classList.add('butt'));
      later(2900, () => { o.el.classList.remove('butt'); o.busy = false; });
    });
  });
}
function scatter() {
  chasing = false;
  beasts.forEach(b => { b.busy = false; b.el.classList.remove('butt', 'graze'); move(b, rnd(5, 93), 1.3, 'running'); });
}

// ---------- asteroid: slow fall onto the herd, light-tan white-out with the scenario name, then fade back ----------
const wait = ms => new Promise(r => setTimeout(r, ms));
async function impact(name, onHit) {
  const flash = document.getElementById('flash'), txt = document.getElementById('flash-text');
  txt.innerHTML = `Simulation controls now showing <b>${name}</b>`;
  if (REDUCED || !document.body.animate) { onHit(); return; }
  const tx = innerWidth * rnd(.35, .65), ty = innerHeight - 55;
  const sx = innerWidth + 120, sy = -140;
  const ang = Math.atan2(sy - ty, sx - tx) * 180 / Math.PI;     // tail points back along the path
  const rock = document.createElement('div'); rock.id = 'rock';
  rock.innerHTML = `<div class="tail" style="transform:rotate(${ang}deg)"></div><div class="stone"></div>`;
  document.body.appendChild(rock);
  rock.querySelector('.stone').animate([{ transform: 'rotate(0)' }, { transform: 'rotate(300deg)' }], { duration: 2600 });
  await rock.animate([{ transform: `translate(${sx}px, ${sy}px) scale(.6)` }, { transform: `translate(${tx}px, ${ty}px) scale(1.1)` }],
    { duration: 2600, easing: 'cubic-bezier(.35,0,.85,.55)', fill: 'forwards' }).finished;
  await flash.animate([{ opacity: 0 }, { opacity: 1 }], { duration: 160, fill: 'forwards' }).finished;
  rock.remove();
  onHit();
  await txt.animate([{ opacity: 0, transform: 'translateY(8px)' }, { opacity: 1, transform: 'none' }], { duration: 450, fill: 'forwards' }).finished;
  await wait(1500);
  await flash.animate([{ opacity: 1 }, { opacity: 0 }], { duration: 1100, easing: 'ease-in', fill: 'forwards' }).finished;
  txt.animate([{ opacity: 0 }], { duration: 0, fill: 'forwards' });
  scatter();
}
scenery();

