// Animals alive at the K-Pg impact. Drawings face right; [viewBox width, height px, fill token, front paths, back paths, eye]
const SPECIES = {
  trike: { name: 'Triceratops', vw: 120, h: 60, fill: '--ink',
    P: ['M2 40 Q20 26 50 26 Q76 26 84 38 L96 40 Q110 42 114 50 L112 56 L104 54 Q96 56 90 54 Q80 58 70 58 Q40 60 24 52 Q10 48 2 40Z','M84 44 L78 18 Q90 8 100 18 L96 42Z','M98 36 L119 22 L102 40Z','M110 46 L117 39 L115 48Z','M30 52 L42 52 L42 74 L48 76 L30 76Z','M72 54 L84 54 L84 74 L90 76 L72 76Z'],
    B: ['M96 40 L114 30 L100 43Z','M44 54 L52 54 L52 76 L44 76Z'], eye: [101, 44] },
  alamo: { name: 'Alamosaurus', vw: 160, h: 84, fill: '--green-ink',
    P: ['M2 44 Q30 36 44 34 Q60 28 80 30 Q96 30 110 18 Q124 6 136 4 L148 4 Q154 6 152 10 L140 12 Q128 14 118 28 Q108 44 100 52 Q86 62 66 62 Q48 62 38 54 Q24 50 2 44Z','M44 54 L56 54 L56 76 L44 76Z','M86 54 L98 54 L98 76 L86 76Z'],
    B: ['M56 58 L65 58 L65 76 L56 76Z','M97 50 L105 48 L105 76 L97 76Z'], eye: [146, 7] },
  pachy: { name: 'Pachycephalosaurus', vw: 112, h: 50, fill: '--pink-ink',
    P: ['M4 40 Q28 32 50 32 Q66 32 76 30 L84 26 Q85 16 95 15 Q106 16 107 26 L108 32 Q106 36 100 36 L92 36 Q88 44 80 48 Q66 56 52 54 Q34 50 4 40Z','M50 50 L60 50 L62 62 L60 74 L68 76 L52 76 L54 62Z','M84 42 L88 50 L86 50 L82 44Z'],
    B: ['M62 50 L68 52 L70 64 L68 74 L74 76 L62 76 L63 64Z'], eye: [100, 27] },
  trex: { name: 'T. rex', vw: 120, h: 74, fill: '--brown',
    P: ['M2 38 Q28 28 50 28 Q66 26 78 22 L100 18 Q114 18 116 28 L114 34 L100 34 L104 38 L90 40 Q84 50 72 54 Q58 58 46 52 Q28 44 2 38Z','M46 48 L60 48 L62 62 L60 74 L68 76 L50 76 L52 62Z','M86 42 L92 46 L90 48 L84 45Z'],
    B: ['M60 50 L68 52 L70 64 L68 74 L74 76 L62 76 L62 64Z'], eye: [102, 23] },
  quetz: { name: 'Quetzalcoatlus', vw: 116, h: 72, fill: '--violet-ink',
    P: ['M30 50 Q40 40 56 40 Q64 42 66 50 Q60 58 44 58 Q32 57 30 50Z','M58 44 Q66 26 72 12 L77 12 Q72 28 64 48Z','M71 14 Q73 5 80 7 L84 10 L114 42 L80 16 Q75 18 71 14Z','M74 8 L63 1 L77 6Z','M56 42 L67 50 L60 62 L50 50Z','M60 48 L67 50 L65 76 L60 76Z','M37 54 L42 54 L40 76 L35 76Z'],
    B: ['M46 56 L50 56 L50 76 L46 76Z'], eye: [78, 10] },
};
const HERB = ['trike', 'pachy', 'alamo'], CARN = ['trex', 'quetz'];
const MAX_H = 8, MAX_C = 6;   // full herd sizes for the drawing (assumed)
const REDUCED = matchMedia('(prefers-reduced-motion: reduce)').matches;
let beasts = [];

function svgFor(s) {
  const f = `var(${s.fill})`, w = Math.round(s.h * s.vw / 80);
  return `<svg viewBox="0 0 ${s.vw} 80" width="${w}" height="${s.h}" role="img" aria-label="${s.name}">` +
    s.B.map(d => `<path d="${d}" fill="${f}" opacity=".6"/>`).join('') + s.P.map(d => `<path d="${d}" fill="${f}"/>`).join('') +
    `<circle cx="${s.eye[0]}" cy="${s.eye[1]}" r="1.7" fill="var(--card)"/></svg>`;
}
function lowest(key, j) {
  const web = DATA.scenarios[key].web; let k = 0;
  web.forEach((r, i) => { if (r[j] < web[k][j]) k = i; });
  return { frac: DATA.scenarios[key].report.levels[j].min, year: DATA.years[k] };
}
function counts(key) {
  const h = lowest(key, 1), c = lowest(key, 2);
  return { h: Math.max(1, Math.round(MAX_H * Math.min(1, h.frac))), c: Math.max(1, Math.round(MAX_C * Math.min(1, c.frac))), hy: h.year, cy: c.year };
}
function buildHerd(key) {
  beasts.forEach(b => clearTimeout(b.t));
  const n = counts(key), field = document.getElementById('field');
  const yr = y => y < 1 ? Math.round(y * 12) + ' mo' : 'yr ' + Math.round(y);
  document.getElementById('herdinfo').innerHTML = key === 'neither'
    ? `Full herd: <b>${n.h} herbivores</b>, <b class="c">${n.c} predators</b>. No impact, nothing lost.`
    : `At the worst point: <b>${n.h} of ${MAX_H} herbivores</b> (${yr(n.hy)}), <b class="c">${n.c} of ${MAX_C} predators</b> (${yr(n.cy)})`;
  const list = [];
  for (let i = 0; i < n.h; i++) list.push(HERB[i % HERB.length]);
  for (let i = 0; i < n.c; i++) list.push(CARN[i % CARN.length]);
  list.sort(() => Math.random() - .5);
  field.innerHTML = '';
  beasts = list.map((sp, i) => {
    const el = document.createElement('div'); el.className = 'beast'; el.style.setProperty('--i', i);
    const x = 6 + (i + .2 + Math.random() * .6) / list.length * 86, dir = Math.random() < .5 ? -1 : 1;
    el.style.left = x + '%';
    el.innerHTML = `<div class="face" style="transform:scaleX(${dir})">${svgFor(SPECIES[sp])}</div>`;
    field.appendChild(el);
    const b = { el, face: el.firstChild, x, dir, t: 0, sp, busy: false };
    if (!REDUCED) b.t = setTimeout(() => act(b), 1500 + Math.random() * 5000);
    return b;
  });
}
// Calm idle behaviour: mostly grazing, sometimes a short walk or a turn.
function act(b) {
  b.t = setTimeout(() => act(b), 4000 + Math.random() * 6000);
  if (b.busy) return;
  const r = Math.random();
  if (b.sp === 'pachy' && r < .3) {
    const mate = beasts.find(o => o !== b && o.sp === 'pachy' && !o.busy);
    if (mate) { headbutt(b, mate); return; }
  }
  if (r < .45) {
    b.el.classList.add('graze'); setTimeout(() => b.el.classList.remove('graze'), 2800);
  } else if (r < .75) {
    const dist = 3 + Math.random() * 6, nx = b.x + b.dir * dist;
    if (nx < 4 || nx > 94) { turn(b); }
    else {
      const secs = dist * 0.5;
      b.el.style.transition = `left ${secs}s linear`; b.el.classList.add('walking');
      b.x = nx; b.el.style.left = nx + '%';
      setTimeout(() => b.el.classList.remove('walking'), secs * 1000);
    }
  } else { turn(b); }
}
// Two Pachycephalosaurus walk together, face each other, and bonk domes a few times.
function headbutt(a, b) {
  a.busy = b.busy = true;
  const [L, R] = a.x <= b.x ? [a, b] : [b, a];
  const fw = document.getElementById('field').clientWidth || innerWidth;
  const half = 31 / fw * 100;                        // ~62 px between centres puts the domes together
  const mid = Math.min(90, Math.max(10, (L.x + R.x) / 2));
  const secs = Math.max(0.8, Math.max(Math.abs(mid - half - L.x), Math.abs(mid + half - R.x)) * 0.35);
  [[L, mid - half, 1], [R, mid + half, -1]].forEach(([o, nx, d]) => {
    o.dir = nx >= o.x ? 1 : -1; o.face.style.transform = `scaleX(${o.dir})`;
    o.el.style.transition = `left ${secs}s linear`; o.el.classList.add('walking');
    o.x = nx; o.el.style.left = nx + '%';
    setTimeout(() => {
      o.el.classList.remove('walking'); o.dir = d; o.face.style.transform = `scaleX(${d})`;
      setTimeout(() => o.el.classList.add('butt'), 500);
      setTimeout(() => { o.el.classList.remove('butt'); o.busy = false; }, 500 + 2400);
    }, secs * 1000);
  });
}
function turn(b) { b.dir *= -1; b.face.style.transform = `scaleX(${b.dir})`; }
function scatter() {
  beasts.forEach(b => {
    const nx = 5 + Math.random() * 88; b.busy = false; b.el.classList.remove('butt'); b.dir = nx > b.x ? 1 : -1; b.face.style.transform = `scaleX(${b.dir})`;
    b.el.style.transition = 'left 1.3s ease-out'; b.el.classList.add('running');
    b.x = nx; b.el.style.left = nx + '%';
    setTimeout(() => b.el.classList.remove('running'), 1300);
  });
}

// Asteroid: slow fall from the top-right onto the herd, white-out with the scenario name, then fade back.
const wait = ms => new Promise(r => setTimeout(r, ms));
async function impact(name, onHit) {
  const flash = document.getElementById('flash'), txt = document.getElementById('flash-text');
  txt.innerHTML = `Simulation controls now showing <b>${name}</b>`;
  if (REDUCED || !document.body.animate) { onHit(); return; }
  const tx = innerWidth * (.35 + Math.random() * .3), ty = innerHeight - 50;
  const sx = innerWidth + 120, sy = -140;
  const ang = Math.atan2(sy - ty, sx - tx) * 180 / Math.PI;     // tail points back along the path
  const rock = document.createElement('div'); rock.id = 'rock';
  rock.innerHTML = `<div class="tail" style="transform:rotate(${ang}deg)"></div><div class="stone"></div>`;
  document.body.appendChild(rock);
  rock.querySelector('.stone').animate([{ transform: 'rotate(0)' }, { transform: 'rotate(300deg)' }], { duration: 2600 });
  await rock.animate([{ transform: `translate(${sx}px, ${sy}px) scale(.6)` }, { transform: `translate(${tx}px, ${ty}px) scale(1.1)` }],
    { duration: 2600, easing: 'cubic-bezier(.35,0,.85,.55)', fill: 'forwards' }).finished;
  await flash.animate([{ opacity: 0 }, { opacity: 1 }], { duration: 160, fill: 'forwards' }).finished;
  rock.remove();
  onHit();
  await txt.animate([{ opacity: 0, transform: 'translateY(8px)' }, { opacity: 1, transform: 'none' }], { duration: 450, fill: 'forwards' }).finished;
  await wait(1500);
  await flash.animate([{ opacity: 1 }, { opacity: 0 }], { duration: 1100, easing: 'ease-in', fill: 'forwards' }).finished;
  txt.animate([{ opacity: 0 }], { duration: 0, fill: 'forwards' });
  scatter();
}

