// ---------- Edmontosaurus skeleton in a death pose (head and neck arched back), drawn for the reset screen ----------
function fossilSVG() {
  const K = [[318, 74], [262, 70], [214, 98], [204, 150], [236, 196], [300, 214], [380, 212], [455, 204], [530, 214], [610, 236], [690, 256], [770, 268]];
  const cr = (p0, p1, p2, p3, t) => { const t2 = t * t, t3 = t2 * t;
    return [0, 1].map(k => .5 * (2 * p1[k] + (-p0[k] + p2[k]) * t + (2 * p0[k] - 5 * p1[k] + 4 * p2[k] - p3[k]) * t2 + (-p0[k] + 3 * p1[k] - 3 * p2[k] + p3[k]) * t3)); };
  const dense = [];
  for (let i = 0; i < K.length - 1; i++) for (let t = 0; t < 1; t += .02)
    dense.push(cr(K[Math.max(0, i - 1)], K[i], K[i + 1], K[Math.min(K.length - 1, i + 2)], t));
  dense.push(K[K.length - 1]);
  const pts = [dense[0]]; let acc = 0;                       // resample every ~13 px along the backbone
  for (let i = 1; i < dense.length; i++) { acc += Math.hypot(dense[i][0] - dense[i - 1][0], dense[i][1] - dense[i - 1][1]); if (acc >= 13) { pts.push(dense[i]); acc = 0; } }
  const N = pts.length, ink = 'var(--ink)', bone = '#e9dccb', out = [];
  const tan = i => { const a = pts[Math.max(0, i - 1)], b = pts[Math.min(N - 1, i + 1)], d = Math.hypot(b[0] - a[0], b[1] - a[1]); return [(b[0] - a[0]) / d, (b[1] - a[1]) / d]; };
  const near = (x) => { let k = 0; pts.forEach((p, i) => { if (Math.abs(p[0] - x) < Math.abs(pts[k][0] - x) && i > 8) k = i; }); return k; };
  const iSh = near(300), iHip = near(455);
  const F = v => v.toFixed(1);
  // ribs (belly side, sweeping back)
  for (let i = iSh; i < iHip - 1; i++) {
    const [x, y] = pts[i], [tx, ty] = tan(i), nx = ty, ny = -tx, f = Math.sin(Math.PI * (i - iSh + 1) / (iHip - iSh + 1)), L = 30 + 62 * f;
    out.push(`<path d="M${F(x)} ${F(y)} Q${F(x - nx * L * .55 + tx * 6)} ${F(y - ny * L * .55 + ty * 6)} ${F(x - nx * L + tx * 22)} ${F(y - ny * L + ty * 22)}" stroke="${ink}" stroke-width="3.2" fill="none" stroke-linecap="round"/>`);
  }
  // scapula + front leg
  out.push(`<path d="M262 196 Q300 186 336 200 L332 210 Q300 204 268 214Z" fill="${bone}" stroke="${ink}" stroke-width="2"/>`);
  out.push(`<path d="M282 214 L292 266 M292 266 L270 304 M292 266 L276 306 M272 304 l-10 10 M272 304 l-2 13 M272 304 l6 12" stroke="${ink}" stroke-width="4" fill="none" stroke-linecap="round"/>`);
  // pelvis: ilium blade, forward pubis paddle, long ischium
  out.push(`<path d="M410 196 Q455 182 500 196 Q470 210 418 208Z" fill="${bone}" stroke="${ink}" stroke-width="2"/>`);
  out.push(`<path d="M440 212 L408 232 Q394 242 384 236 Q392 226 430 208Z" fill="${bone}" stroke="${ink}" stroke-width="2"/>`);
  out.push(`<path d="M462 212 L520 262 L514 266 L454 218Z" fill="${bone}" stroke="${ink}" stroke-width="2"/>`);
  // hind legs (far leg fainter)
  const leg = (dx, dy, op) => out.push(`<g opacity="${op}" transform="translate(${dx} ${dy})"><path d="M452 214 L430 296 M430 296 L478 352 M478 352 L508 370" stroke="${ink}" stroke-width="7" fill="none" stroke-linecap="round"/><path d="M508 370 l20 -4 M508 370 l22 4 M508 370 l16 12" stroke="${ink}" stroke-width="4" fill="none" stroke-linecap="round"/><circle cx="452" cy="214" r="7" fill="${bone}" stroke="${ink}" stroke-width="2"/></g>`);
  leg(26, 6, .45); leg(0, 0, 1);
  // ossified tendons: the criss-cross lattice along a hadrosaur's back
  const iT0 = near(380), iT1 = near(610);
  for (let i = iT0; i < iT1; i += 2) {
    const [x, y] = pts[i], [tx, ty] = tan(i), nx = ty, ny = -tx;
    out.push(`<path d="M${F(x + nx * 8 - tx * 14)} ${F(y + ny * 8 - ty * 14)} L${F(x + nx * 30 + tx * 14)} ${F(y + ny * 30 + ty * 14)} M${F(x + nx * 30 - tx * 14)} ${F(y + ny * 30 - ty * 14)} L${F(x + nx * 8 + tx * 14)} ${F(y + ny * 8 + ty * 14)}" stroke="${ink}" stroke-width="1" opacity=".55"/>`);
  }
  // vertebrae with neural spines (up) and tail chevrons (down)
  pts.forEach(([x, y], i) => {
    const [tx, ty] = tan(i), nx = ty, ny = -tx, ang = Math.atan2(ty, tx) * 180 / Math.PI;
    const tail = i > iHip, neck = i < iSh, u = tail ? 1 - (i - iHip) / (N - iHip) : 1;
    const sz = neck ? 5.5 : tail ? 3 + 4 * u : 7;
    const sp = neck ? 7 : tail ? 6 + 26 * u * u : 30;
    out.push(`<path d="M${F(x)} ${F(y)} L${F(x + nx * sp)} ${F(y + ny * sp)}" stroke="${ink}" stroke-width="${tail ? 2.4 : 3}" stroke-linecap="round"/>`);
    if (tail && u > .12) out.push(`<path d="M${F(x)} ${F(y)} L${F(x - nx * (sp * .8) + tx * 4)} ${F(y - ny * (sp * .8) + ty * 4)}" stroke="${ink}" stroke-width="2" stroke-linecap="round"/>`);
    out.push(`<rect x="${F(x - sz)}" y="${F(y - sz * .75)}" width="${F(sz * 2)}" height="${F(sz * 1.5)}" rx="${F(sz * .5)}" fill="${bone}" stroke="${ink}" stroke-width="1.6" transform="rotate(${F(ang)} ${F(x)} ${F(y)})"/>`);
  });
