input.new_string:
// Plants follow the model's producers level (web column 0) at its lowest point: missing trees stand dead, missing ferns leave bare ground.
const FERN_TILE = 'data:image/svg+xml,' + encodeURIComponent(frondTile());
function deadTree(kind, h) {
  if (kind === 'a') return `<svg viewBox="0 0 60 120" height="${h}" width="${h / 2}"><rect x="28" y="30" width="4" height="90" fill="var(--brown)"/><path d="M30 52 L18 44 M30 70 L42 62 M30 88 L20 82" stroke="var(--brown)" stroke-width="2"/></svg>`;
  return `<svg viewBox="0 0 60 50" height="${h}" width="${h * 1.2}"><path d="M25 50 L26 34 L34 32 L35 50Z" fill="var(--brown)"/></svg>`;
}
function scenery(frac) {
  const T = [[4, 'a', 118], [21, 'c', 46], [37, 'f', 92], [58, 'a', 104], [74, 'c', 40], [90, 'f', 84]];
  const alive = Math.round(T.length * Math.min(1, frac));
  const keep = new Set([0, 3, 1, 4, 2, 5].slice(0, alive));       // which slots stay green
  document.getElementById('trees').innerHTML = T.map(([x, k, h], i) => {
    const s = keep.has(i) ? (k === 'a' ? araucaria(h) : k === 'c' ? cycad(h) : treefern(h)) : deadTree(k === 'f' ? 'a' : k, k === 'a' ? h * .8 : h * .7);
    return `<div class="tree" style="left:${x}%">${s}</div>`;
  }).join('');
  const g = document.querySelector('.grass'), W = g.clientWidth || innerWidth, full = Math.ceil(W / 60);
  const n = Math.round(full * Math.min(1, frac));
  const slots = [...Array(full).keys()].sort(() => Math.random() - .5).slice(0, n);
  g.innerHTML = slots.map(i => `<span class="fern" style="left:${(i * 60 - 18).toFixed(0)}px;background-image:url('${FERN_TILE}')"></span>`).join('');
}

