toolUseResult.originalFile:
/* fern-and-tree "taskbar" of animals */
.bar { position: fixed; left: 0; right: 0; bottom: 0; height: calc(var(--bar) + env(safe-area-inset-bottom, 0px)); z-index: 20;
  background: linear-gradient(#efe6da, var(--peach)); border-top: 1px solid var(--line); overflow: hidden; }
.herdinfo { position: absolute; top: 5px; left: max(16px, env(safe-area-inset-left, 0px)); font-size: 13px; z-index: 3;
  background: rgb(230 220 207 / .88); padding: 1px 8px; border-radius: 3px; max-width: calc(100% - 32px); }
.herdinfo b { color: var(--green-ink); } .herdinfo b.c { color: var(--brown); }
#trees { position: absolute; left: 0; right: 0; bottom: calc(14px + env(safe-area-inset-bottom, 0px)); height: 120px; opacity: .5; }
.tree { position: absolute; bottom: 0; transform: translateX(-50%); }
.tree svg { display: block; }
.field { position: absolute; left: 0; right: 0; bottom: calc(12px + env(safe-area-inset-bottom, 0px)); height: 110px; }
.grass { position: absolute; left: 0; right: 0; bottom: 0; height: calc(36px + env(safe-area-inset-bottom, 0px)); z-index: 2; pointer-events: none; }
.beast { position: absolute; bottom: 0; transform: translateX(-50%); transition: left 3s linear; }
.beast.flyer { bottom: 52px; }
.face { transition: transform .45s ease-in-out; transform-origin: 50% 100%; }
.beast svg { display: block; overflow: visible; transform-origin: 30% 100%; animation: breathe 3.6s ease-in-out infinite; animation-delay: calc(var(--i) * -0.41s); }
.beast.flyer svg { transform-origin: 50% 50%; animation: soar 3.2s ease-in-out infinite; animation-delay: calc(var(--i) * -0.5s); }
.beast.graze svg { animation: graze 2.8s ease-in-out 1; }
.beast.butt svg { animation: butt .8s ease-in-out 3; }
.beast.walking svg { animation: step .38s ease-in-out infinite alternate; }
.beast.running svg { animation: step .16s ease-in-out infinite alternate; }
.beast.flyer.gliding svg, .beast.flyer.running svg { animation: soar 1.6s ease-in-out infinite; }
@keyframes breathe { 0%,100% { transform: scaleY(1); } 50% { transform: scaleY(1.02); } }
@keyframes soar { 0%,100% { transform: translateY(-5px) rotate(-2deg); } 50% { transform: translateY(5px) rotate(2deg); } }
@keyframes graze { 0%,100% { transform: rotate(0); } 20%,40%,60% { transform: rotate(6deg); } 30%,50% { transform: rotate(3.5deg); } }
@keyframes butt { 0%,100% { transform: none; } 35% { transform: translateX(-7px) rotate(-4deg); } 55% { transform: translateX(6px) rotate(5deg); } 70% { transform: translateX(2px); } }
@keyframes step { from { transform: translateY(0) rotate(-1deg); } to { transform: translateY(-3px) rotate(1deg); } }

/* fiery asteroid + light-tan white-out */
#rock { position: fixed; left: 0; top: 0; width: 0; height: 0; z-index: 60; pointer-events: none; }
#rock .tail { position: absolute; left: 0; top: -36px; width: 420px; height: 72px; transform-origin: 0 50%; }
#rock .tail::before, #rock .tail::after { content: ""; position: absolute; inset: 0; border-radius: 0 50% 50% 0 / 0 50% 50% 0;
  clip-path: polygon(0 20%, 100% 46%, 100% 54%, 0 80%); animation: flicker .12s ease-in-out infinite alternate; }
#rock .tail::before { background: linear-gradient(90deg, #ffd84d, #ff8a1f 25%, #d9381e 55%, rgb(120 30 10 / 0)); filter: blur(4px); }
#rock .tail::after { inset: 18px 0 18px 0; clip-path: polygon(0 10%, 70% 46%, 70% 54%, 0 90%);
  background: linear-gradient(90deg, #fffbe6, #ffe27a 30%, rgb(255 160 40 / 0) 70%); filter: blur(2px); animation-duration: .09s; }
@keyframes flicker { from { transform: scaleY(.88); opacity: .9; } to { transform: scaleY(1.08); opacity: 1; } }
#rock .stone { position: absolute; left: -38px; top: -38px; width: 76px; height: 76px; border-radius: 48% 52% 46% 54% / 52% 46% 54% 48%;
  background:
    radial-gradient(circle at 62% 38%, rgb(30 24 22 / .55) 0 6px, transparent 7px),
    radial-gradient(circle at 44% 64%, rgb(30 24 22 / .45) 0 8px, transparent 9px),
    radial-gradient(circle at 26% 74%, #fffbe6 0, #ffd84d 18%, #ff8a1f 38%, #c2401d 58%, #3b302c 82%);
  box-shadow: 0 0 18px 6px rgb(255 216 77 / .9), 0 0 44px 18px rgb(255 138 31 / .65), 0 0 90px 40px rgb(217 56 30 / .35);
  animation: glow .15s ease-in-out infinite alternate; }
@keyframes glow { to { box-shadow: 0 0 22px 8px rgb(255 216 77 / 1), 0 0 52px 22px rgb(255 138 31 / .7), 0 0 100px 46px rgb(217 56 30 / .4); } }
#flash { position: fixed; inset: 0; z-index: 70; pointer-events: none; opacity: 0; background: #efe6da;
  display: grid; place-items: center; padding: 16px; }
#flash p { margin: 0; font-size: clamp(24px, 4vw, 44px); text-align: center; color: var(--ink); opacity: 0; text-wrap: balance; }
#flash p b { color: var(--brown); }
#flash svg.fossil { position: absolute; width: min(94vw, 1150px); max-height: 82vh; height: auto; opacity: .2; }
#flash p { position: relative; background: rgb(230 220 207 / .88); border: 1px solid var(--line); border-radius: 8px;
  padding: .45em .9em; box-shadow: 0 6px 24px rgb(44 36 26 / .12); max-width: min(90vw, 900px); }
#flash .fossil-cap { position: absolute; bottom: calc(18px + env(safe-area-inset-bottom, 0px)); left: 0; right: 0; text-align: center; font-style: italic; font-size: 14px; opacity: .7; }

