// ---------- one animal ----------
function spawn(sp, x, dir, i) {
  const s = SPECIES[sp], el = document.createElement('div');
  el.className = 'beast' + (s.fly ? ' flyer' : ''); el.style.setProperty('--i', i);
  el.style.left = x + '%';
  el.innerHTML = `<div class="face" style="transform:scaleX(${dir})">${svgFor(s)}</div>`;
  document.getElementById('field').appendChild(el);
  return { el, face: el.firstChild, x, dir, sp, t: 0, busy: false, gone: false };
}
function face(b, d) { b.dir = d; b.face.style.transform = `scaleX(${d})`; }
function move(b, nx, secs, cls) {
  face(b, nx >= b.x ? 1 : -1);
  b.el.style.transition = `left ${secs}s ${cls === 'running' ? 'ease-out' : 'linear'}`;
  b.el.classList.add(cls); b.x = nx; b.el.style.left = nx + '%';
  return new Promise(r => later(secs * 1000, () => { b.el.classList.remove(cls); r(); }));
}
function schedule(b, ms) { clearTimeout(b.t); if (!REDUCED) b.t = later(ms ?? rnd(4000, 10000), () => act(b)); }

function buildHerd(key) {
  beasts.forEach(b => { clearTimeout(b.t); b.gone = true; });
  chasing = false;
  const n = counts(key), field = document.getElementById('field'), plants = lowest(key, 0);
  scenery(plants.frac); lake(plants.frac);
  const yr = y => y < 1 ? Math.round(y * 12) + ' mo' : 'yr ' + Math.round(y);
  document.getElementById('herdinfo').innerHTML = key === 'neither'
    ? `Full herd: <b>${n.h} herbivores</b>, <b class="c">${n.c} predators</b>, all plants. No impact, nothing lost.`
    : `At the worst point: <b>plants ${Math.round(plants.frac * 100)}%</b> (${yr(plants.year)}), <b>${n.h} of ${MAX_H} herbivores</b> (${yr(n.hy)}), <b class="c">${n.c} of ${MAX_C} predators</b> (${yr(n.cy)})`;
  const list = [];
  for (let i = 0; i < n.h; i++) list.push(HERB[i % HERB.length]);
  for (let i = 0; i < n.c; i++) list.push(CARN[i % CARN.length]);
  list.sort(() => Math.random() - .5);
  field.innerHTML = '';
  beasts = list.map((sp, i) => {
    const b = spawn(sp, SPECIES[sp].fly ? rnd(8, 90) : 5 + (i + rnd(.2, .8)) / list.length * (LAND - 6), Math.random() < .5 ? -1 : 1, i);
    schedule(b, rnd(1500, 6000));
    return b;
  });
}

// ---------- behaviours: graze, stroll, turn, wander off (and a new kind walks on), T. rex chase, Pachy headbutt ----------
function act(b) {
  if (b.gone) return;
  schedule(b);
  if (b.busy) return;
  const r = Math.random(), s = SPECIES[b.sp];
  if (s.fly) {                                     // Quetzalcoatlus glides around overhead
    if (r < .1) return leave(b);
    return void move(b, Math.min(94, Math.max(6, b.x + rnd(-30, 30))), rnd(4, 7), 'gliding');
  }
  if (b.sp === 'trex' && r < .2 && !chasing) { const prey = beasts.find(o => SPECIES[o.sp].diet === 'h' && !o.busy && !o.gone); if (prey) return chase(b, prey); }
  if (b.sp === 'pachy' && r < .3) { const mate = beasts.find(o => o !== b && o.sp === 'pachy' && !o.busy && !o.gone); if (mate) return headbutt(b, mate); }
  if (r < .08) return leave(b);
  if (r < .5) { b.el.classList.add('graze'); later(2800, () => b.el.classList.remove('graze')); return; }
  if (r < .8) {
    const nx = b.x + b.dir * rnd(3, 9);
    if (nx < 4 || nx > LAND) return face(b, -b.dir);
    return void move(b, nx, Math.abs(nx - b.x) * .5, 'walking');
  }
  face(b, -b.dir);
}

