// ---------- Quetzalcoatlus standing pose (for wading at the ledge) ----------
const QUETZ_STAND = `<svg class="stand" viewBox="0 0 116 80" width="87" height="60" aria-hidden="true"><g fill="var(--violet-ink)">
  <path d="M30 50 Q40 40 56 40 Q64 42 66 50 Q60 58 44 58 Q32 57 30 50Z"/><path d="M58 44 Q66 26 72 12 L77 12 Q72 28 64 48Z"/>
  <path d="M71 14 Q73 5 80 7 L84 10 L114 42 L80 16 Q75 18 71 14Z"/><path d="M74 8 L63 1 L77 6Z"/><path d="M56 42 L67 50 L60 62 L50 50Z"/>
  <path d="M60 48 L67 50 L65 76 L60 76Z"/><path d="M37 54 L42 54 L40 76 L35 76Z"/><path d="M46 56 L50 56 L50 76 L46 76Z" opacity=".6"/></g>
  <circle cx="78" cy="10" r="1.7" fill="var(--card)"/></svg>`;
const LEDGE_X = 53.4;      // percent of bar width: the rock ledge at the foot of the cliff
let hunting = false;
async function hunt(b) {
  hunting = true; b.busy = true;
  await move(b, LEDGE_X, Math.max(2.5, Math.abs(LEDGE_X - b.x) * .09), 'gliding');
  if (b.gone) { hunting = false; return; }
  face(b, 1); b.el.classList.add('perched');                 // lands and wades at the water's edge
  if (school) seaGo(school, 5, 10, 2.2);                     // the fish school drifts into the shallows
  await wait(2800);
  b.el.classList.add('snatch');
  later(450, eatFish);
  await wait(1400);
  b.el.classList.remove('snatch', 'perched');
  await wait(600);
  if (!b.gone) await move(b, rnd(8, LAND), rnd(3, 5), 'gliding');
  b.busy = false; hunting = false;
}

// ---------- the sea: depth cross-section, plankton (producers), small prey (herbivore level), plesiosaur + Mosasaurus ----------
const SEA_INK = '#2f4f52';
const FISH = `<svg viewBox="0 0 24 10" width="18" height="8"><path d="M22 5 Q16 0 8 4 L2 1 L3 5 L2 9 L8 6 Q16 10 22 5Z" fill="#dbe6e1" stroke="${SEA_INK}" stroke-width=".6"/><circle cx="18.5" cy="4.4" r=".9" fill="${SEA_INK}"/></svg>`;
const AMMONITE = `<svg viewBox="0 0 34 28" width="30" height="25"><circle cx="13" cy="14" r="11" fill="#e1bca7" stroke="#7a5a43" stroke-width="1.2"/>
  <path d="M13 14 m0 -3 a3 3 0 1 1 -3 3 a6 6 0 0 1 6 -6 a8.5 8.5 0 0 1 8.5 8.5" fill="none" stroke="#7a5a43" stroke-width="1.1"/>
  <path d="M13 3 L13 6 M21 6 L19 8 M24 14 L21 14 M5 6 L7 8 M2 14 L5 14 M5 22 L7 20 M13 25 L13 22" stroke="#7a5a43" stroke-width=".8"/>
  <path d="M23 18 Q28 18 33 15 M23 20 Q28 21 33 21 M22 22 Q26 25 31 26" stroke="#94608f" stroke-width="1.3" fill="none" stroke-linecap="round"/></svg>`;
const BELEMNITE = `<svg viewBox="0 0 38 12" width="32" height="10"><path d="M2 6 Q4 2 12 3 L26 4 Q30 6 26 8 L12 9 Q4 10 2 6Z" fill="#c59fc5" stroke="#94608f" stroke-width=".8"/>
  <path d="M26 5 Q31 3 36 3 M27 6 L37 6 M26 7 Q31 9 36 9" stroke="#94608f" stroke-width="1.1" fill="none" stroke-linecap="round"/><circle cx="24.5" cy="5.4" r=".9" fill="${SEA_INK}"/></svg>`;
const TURTLE = `<svg viewBox="0 0 30 16" width="24" height="13"><path d="M17 11 l5 4 l-6 -2Z M10 11 l-5 4 l6 -2Z M18 5 l7 -4 l-3 5Z" fill="#4f7a58"/>
  <ellipse cx="14" cy="8" rx="8" ry="5" fill="#6b7d4a" stroke="#4f5a33" stroke-width=".8"/><path d="M9 8 h10 M14 3.5 v9" stroke="#4f5a33" stroke-width=".6"/>
  <circle cx="24.5" cy="7" r="2.8" fill="#8a9a63"/><circle cx="25.6" cy="6.4" r=".7" fill="${SEA_INK}"/></svg>`;
const MOVERS = {
  plesio: { svg: () => PLESIO, xr: [26, 80], yr: [30, 74], secs: [6, 10], wait: [1.5, 5] },
  mosa: { svg: () => MOSA, xr: [26, 80], yr: [25, 70], secs: [6, 10], wait: [1.5, 5] },
  school: { svg: () => [[0, 0], [14, -6], [16, 6], [30, 0], [6, 10]].map(([x, y]) => `<span class="fish" style="left:${x}px;top:${y}px">${FISH}</span>`).join(''),
    xr: [10, 85], yr: [12, 60], secs: [4, 7], wait: [1, 4] },
  ammonite: { svg: () => AMMONITE, xr: [8, 92], yr: [25, 80], secs: [10, 16], wait: [2, 6] },
  belemnite: { svg: () => BELEMNITE, xr: [8, 92], yr: [20, 75], secs: [1.6, 2.8], wait: [4, 9] },
  turtle: { svg: () => TURTLE, xr: [8, 92], yr: [4, 14], secs: [7, 11], wait: [2, 5] },
};
let seaLife = [], school = null;
function seaSpawn(kind, x, y) {
  const L = document.getElementById('lake'), el = document.createElement('div');
  el.className = 'swimmer ' + kind;
  el.innerHTML = `<div class="face">${MOVERS[kind].svg()}</div>`;
  el.style.left = x + '%'; el.style.top = y + '%'; L.appendChild(el);
  const m = { el, face: el.firstChild, x, y, kind, dir: 1, gone: false, t: 0 };
  if (!REDUCED) m.t = later(rnd(500, 3000), () => wander(m));
  return m;
}
function seaGo(m, nx, ny, secs) {
  m.dir = nx >= m.x ? 1 : -1; m.face.style.transform = `scaleX(${m.dir})`;
  m.el.style.transition = `left ${secs}s ease-in-out, top ${secs}s ease-in-out`;
  m.x = nx; m.y = ny; m.el.style.left = nx + '%'; m.el.style.top = ny + '%';
}
function wander(m) {
  if (m.gone) return;
  const o = MOVERS[m.kind], secs = rnd(...o.secs);
  if (!(m === school && hunting)) seaGo(m, rnd(...o.xr), rnd(...o.yr), secs);
  m.t = later((secs + rnd(...o.wait)) * 1000, () => wander(m));
}
function eatFish() {
  if (!school) return;
  const fish = school.el.querySelectorAll('.fish');
  if (fish.length > 1) { fish[fish.length - 1].remove(); return; }
  const old = school; old.gone = true; clearTimeout(old.t); old.el.remove(); school = null;
  later(9000, () => { if (seaLife.includes(old)) { school = seaSpawn('school', 90, 30); seaLife[seaLife.indexOf(old)] = school; } });
}
function sea(plantFrac, herbFrac) {
  const L = document.getElementById('lake');
  const n = Math.round(36 * Math.min(1, plantFrac));        // plankton dots follow the producers level
