  <path d="M60 48 L67 50 L65 76 L60 76Z"/><path d="M37 54 L42 54 L40 76 L35 76Z"/><path d="M46 56 L50 56 L50 76 L46 76Z" opacity=".6"/></g>
  <circle cx="78" cy="10" r="1.7" fill="var(--card)"/></svg>`;
const LEDGE_X = 53.4;      // percent of bar width: the rock ledge at the foot of the cliff
