  await wait(2800);
  b.el.classList.add('snatch');
  later(450, eatFish);
  await wait(1400);
  b.el.classList.remove('snatch', 'perched');
  await wait(600);
  if (!b.gone) await move(b, rnd(8, LAND), rnd(3, 5), 'gliding');
  b.busy = false; hunting = false;
}

// ---------- the sea: depth cross-section, plankton (producers), small prey (herbivore level), plesiosaur + Mosasaurus ----------
