  <path d="M26 5 Q31 3 36 3 M27 6 L37 6 M26 7 Q31 9 36 9" stroke="#94608f" stroke-width="1.1" fill="none" stroke-linecap="round"/><circle cx="24.5" cy="5.4" r=".9" fill="${SEA_INK}"/></svg>`;
