const MOSA = `<svg viewBox="0 0 160 50" width="116" height="36" aria-label="Mosasaurus">
  <path d="M84 22 Q92 12 104 10 Q96 18 92 23Z" fill="#3d4a3c" opacity=".55"/>
  <path d="M20 28 Q50 18 90 20 Q115 21 128 22 L156 25 Q158 28 150 29 L130 30 Q140 33 128 34 Q100 38 70 36 Q40 34 20 28Z" fill="#3d4a3c"/>
