  el.style.left = x + '%'; el.style.top = y + '%'; L.appendChild(el);
  const m = { el, face: el.firstChild, x, y, kind, dir: 1, gone: false, busy: false, t: 0 };
  if (!REDUCED) m.t = later(rnd(500, 3000), () => wander(m));
  return m;
}
function seaGo(m, nx, ny, secs, ease) {
  m.dir = nx >= m.x ? 1 : -1; m.face.style.transform = `scaleX(${m.dir})`;
  m.el.style.transition = `left ${secs}s ${ease || 'ease-in-out'}, top ${secs}s ${ease || 'ease-in-out'}`;
  m.x = nx; m.y = ny; m.el.style.left = nx + '%'; m.el.style.top = ny + '%';
}
function frantic(m, nx, ny, secs) {        // fast, wiggly dash
  m.el.classList.add('frantic'); seaGo(m, nx, ny, secs, 'ease-out');
  later(secs * 1000, () => m.el.classList.remove('frantic'));
}
function wander(m) {
  if (m.gone) return;
  const o = MOVERS[m.kind], secs = rnd(...o.secs);
  m.t = later((secs + rnd(...o.wait)) * 1000, () => wander(m));
  if (m.busy || (m === school && hunting)) return;
