  seaGo(m, rnd(...o.xr), rnd(...o.yr), secs);
}
// plesiosaur or Mosasaurus chases a prey animal, which flees frantically
function seaChase(pred, prey) {
  seaChasing = true; pred.busy = prey.busy = true;
  const d = prey.x >= pred.x ? 1 : -1;
  const gx = Math.min(94, Math.max(6, prey.x + d * rnd(25, 40))), gy = Math.min(85, Math.max(8, prey.y + rnd(-25, 25)));
  frantic(prey, gx, gy, 1.6);
  later(300, () => frantic(pred, Math.min(90, Math.max(10, gx - d * 10)), gy, 1.7));
  later(2600, () => { pred.busy = prey.busy = false; seaChasing = false; });
}
// asteroid on its way: everything in the sea swims frantically
function seaPanic() {
  seaLife.forEach(m => { if (m.gone) return; m.busy = true; frantic(m, rnd(8, 92), rnd(10, 80), 1.1); later(1200, () => { m.busy = false; }); });
}
function eatFish() {
  if (!school) return;
  const fish = school.el.querySelectorAll('.fish');
  if (fish.length > 1) { fish[fish.length - 1].remove(); return; }
  const old = school; old.gone = true; clearTimeout(old.t); old.el.remove(); school = null;
  later(9000, () => { if (seaLife.includes(old)) { school = seaSpawn('school', 90, 30); seaLife[seaLife.indexOf(old)] = school; } });
}
function sea(plantFrac, herbFrac) {
  const L = document.getElementById('lake');
  const n = Math.round(36 * Math.min(1, plantFrac));        // plankton dots follow the producers level
  let dots = '';
  for (let i = 0; i < n; i++) dots += `<i class="plankton" style="left:${rnd(4, 96).toFixed(1)}%;top:${rnd(4, 30).toFixed(1)}%;animation-delay:${(-rnd(0, 6)).toFixed(2)}s"></i>`;
  L.querySelector('.plankton-layer').innerHTML = dots;
  seaChasing = false;
  seaLife.forEach(m => { m.gone = true; clearTimeout(m.t); if (!MOVERS[m.kind].pred) m.el.remove(); });
  const keep = seaLife.filter(m => MOVERS[m.kind].pred);
  keep.forEach(m => { m.gone = false; m.busy = false; m.el.classList.remove('frantic'); if (!REDUCED) m.t = later(rnd(500, 2000), () => wander(m)); });
  const units = Math.max(1, Math.round(6 * Math.min(1, herbFrac)));   // small prey follow the herbivore level
  const KINDS = ['school', 'ammonite', 'turtle', 'belemnite', 'ammonite', 'turtle'];
  const prey = KINDS.slice(0, units).map(k => seaSpawn(k, rnd(15, 85), rnd(...MOVERS[k].yr)));
  school = prey.find(m => m.kind === 'school') || null;
  seaLife = (keep.length ? keep : [seaSpawn('plesio', 38, 60), seaSpawn('mosa', 70, 40)]).concat(prey);
}

