/* center split: sea cliff + sea on the right half */
#lake { left: 52%; right: 0; width: auto; top: 58px; clip-path: none; }
#cliff { position: absolute; left: 40%; width: 16%; bottom: 0; height: 120px; z-index: 2; pointer-events: none; }
.swimmer { position: absolute; transform: translate(-50%, -50%); }
.swimmer .face { transition: transform .5s ease-in-out; }
.swimmer svg { display: block; }
.swimmer.plesio svg, .swimmer.mosa svg { animation: paddle 2.6s ease-in-out infinite; }
.swimmer.ammonite svg { animation: drift 3s ease-in-out infinite alternate; }
.swimmer.turtle svg { animation: paddle 1.4s ease-in-out infinite; }
.swimmer.school .face { position: relative; width: 50px; height: 20px; }
.fish { position: absolute; animation: drift 1.2s ease-in-out infinite alternate; }
.fish:nth-child(2n) { animation-delay: -.6s; }
.swimmer.frantic svg, .swimmer.frantic .fish { animation: frantic .14s ease-in-out infinite alternate !important; }
@keyframes frantic { from { transform: translateY(-2px) rotate(-6deg); } to { transform: translateY(2px) rotate(6deg); } }
/* flying and wading Quetzalcoatlus always sits in front of the water */
.beast.flyer { z-index: 4; }
.face svg.stand { display: none; }
.beast.perched { bottom: 62px; }
